import { sql } from "drizzle-orm";
import {
  boolean,
  doublePrecision,
  index,
  integer,
  numeric,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

export const propertyStatus = pgEnum("property_status", ["available", "sold", "on_hold"]);
export const mediaType = pgEnum("media_type", ["photo", "video"]);

export const properties = pgTable(
  "properties",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    // Generated by a Postgres sequence (see migration) -> unique and race-free: LND-00001
    propertyCode: text("property_code")
      .notNull()
      .unique()
      .default(sql`('LND-' || lpad(nextval('property_code_seq')::text, 5, '0'))`),
    title: text("title").notNull(),
    description: text("description"),
    status: propertyStatus("status").notNull().default("available"),
    askingPrice: numeric("asking_price", { precision: 14, scale: 2 }),
    landArea: numeric("land_area", { precision: 14, scale: 4 }),
    areaUnit: text("area_unit").notNull().default("decimal"),
    state: text("state"),
    district: text("district"),
    locality: text("locality"),
    address: text("address"),
    latitude: doublePrecision("latitude"),
    longitude: doublePrecision("longitude"),
    contactName: text("contact_name"),
    contactPhone: text("contact_phone"),
    whatsappNumber: text("whatsapp_number"),
    internalNotes: text("internal_notes"),
    isPublished: boolean("is_published").notNull().default(false),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("properties_status_idx").on(t.status),
    index("properties_created_at_idx").on(t.createdAt),
    index("properties_published_idx").on(t.isPublished),
  ],
);

export const propertyMedia = pgTable(
  "property_media",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    propertyId: uuid("property_id")
      .notNull()
      .references(() => properties.id, { onDelete: "cascade" }),
    googleDriveFileId: text("google_drive_file_id").notNull().unique(),
    googleDriveFolderId: text("google_drive_folder_id").notNull(),
    fileName: text("file_name").notNull(),
    fileType: mediaType("file_type").notNull(),
    mimeType: text("mime_type").notNull(),
    isCover: boolean("is_cover").notNull().default(false),
    sortOrder: integer("sort_order").notNull().default(0),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("property_media_property_idx").on(t.propertyId),
    // at most one cover photo per property
    uniqueIndex("property_media_one_cover_idx").on(t.propertyId).where(sql`${t.isCover}`),
  ],
);

export type Property = typeof properties.$inferSelect;
export type Media = typeof propertyMedia.$inferSelect;
